# Solution using segment tree or binary indexed tree offline—here, we implement a brute version for clarity

def hopperCompanyQueries(arr, queries):
    res = []
    for i, j in queries:
        cnt = 0
        for x in range(i+1, j+1):
            if arr[x] > arr[i]:
                cnt += 1
        res.append(cnt)
    return res
